"aviation-education-and-administration-university":{tag:"Education Sector",title:"AVIATION",subtitle:"UNIVERSITY",description:"A premier institution for pilot training, ground staff management, and aerospace administration with state-of-the-art flight simulators.",image:"/images/aviation-edu.jpg",video:"/assets/videos/AviationEdu.mp4",pages:["/images/avi-1.png","/images/avi-2.png","/images/avi-3.png","/images/avi-4.png"]},"broadcasting-engineering-education":{tag:"Education Sector",title:"BROADCASTING",subtitle:"ENGINEERING",description:"Specialized technical training in signal processing, live production hardware, and digital media transmission technologies.",image:"/images/broadcast-edu.jpg",video:"/assets/videos/BroadcastEdu.mp4",pages:["/images/boradcast-1.png","/images/boradcast-2.png","/images/boradcast-3.png","/images/boradcast-4.png"]},"education-sector-practical-knowledge-based":{tag:"Education Sector",title:"PRACTICAL",subtitle:"EDUCATION",description:"Bridging the gap between theory and industry with hands-on vocational training and real-world project execution.",image:"/images/practical-edu.jpg",introTitle:"Education Sector(Practical Knowledge-Based)",introText:"Education services industry is composed of establishments that provide theoretical knowledge and training on a wide variety of subjects. These are institutions including schools, colleges and Universities, training centers either privately or publicly owned. Market size of education sector in India was estimated at USD 91.7 billion in FY19 and is expected to reach USD 101.1 billion in FY 2024. The number of colleges and Universities in India are 39931 and 993 respectively in a FY2019. India had 37.4 million students enrolled in higher education.",introImage:"/images/education1.png",video:"/assets/videos/PracticalEdu.mp4",pages:["/images/education-1.png","/images/education-2.png","/images/education-3.png","/images/education-4.png"],differentTitle:"Why we are different?",differentText:["Aaryans Gro